          if (z.count === 0 || (Math.abs(z.avgVx) < 0.1 && Math.abs(z.avgVy) < 0.1)) return null;

          // Scale vector for visibility
          const scale = 20; 
          return (
            <line
              key={`flow-${z.id}`}
              x1={`${z.cx}%`} y1={`${z.cy}%`}
              x2={`${z.cx + z.avgVx * scale}%`} y2={`${z.cy + z.avgVy * scale}%`}
